Given a 2D matrix mat[][] of dimension n x m, find the area of largest submatrix whose sum is 0.Examples: Input: mat[][] = [[9,  7, 16,  5], [1, -6, -7,  3], [1,  8,  7,  9], [7, -2,  0, 10]]Output: 6Explanation: Input: mat[][] = [[1,  2,  3], [-3, -2, -1], [1,  7,  5]]Output: 6Explanation:  Input: mat[][] = [[1, -1], [-1, 1]]Output: 4Explanation: The largest submatrix with sum 0 is [[1, -1], [-1, 1]].Try It YourselfTable of Content[Naive Approach] Using four Nested Loops - O(n^4) Time and O(n^2) Space[Expected Approach] Using Prefix Sum - O(n^3) Time and O(n) Space[Naive Approach] Using four Nested Loops - O(n^4) Time and O(n^2) SpaceThe naive solution for this problem is to check the sum of every possible rectangle in given 2D array. For this we can use four nested loop to fix the upper row, bottom row, left column and right column of the sub matrix. Now for each such sub matrix we can find its sum using a 2D prefix sum matrix in constant time. If this calculated sum is equal to 0 then update the maximum area found.[Expected Approach] Using Prefix Sum - O(n^3) Time and O(n) SpaceThe idea is to iterate over all pairs of rows to fix the top and bottom boundaries (height) of the zero-sum submatrix. Then, for each pair, we find the maximum width such that the total sum of the submatrix is zero.To find the width of largest submatrix with zero sum for a given top and bottom row pair:For a given top-bottom pair, we compute the column-wise cumulative sum in a temporary array temp[].Now find the length of Longest Subarray with 0 Sum in temp[] array.The Length of longest subarray with 0 Sum in temp[] array will also be the width of the largest 0-sum submatrix.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

//Driver Code Ends

int maxZeroSumSubarray(vector<int> &arr)
{
    int prefSum = 0;
    int maxLength = 0;

    // Hash map to store the first
    // index of each prefix sum.
    unordered_map<int, int> mp;

    // Iterate through the array to
    // find subarrays with zero sum.
    for (int i = 0; i < arr.size(); i++)
    {
        prefSum += arr[i];

        if (prefSum == 0)
            maxLength = i + 1;

        if (mp.find(prefSum) != mp.end())
        {
            // If this prefSum repeats,
            // find subarray length.
            maxLength = max(maxLength, (i - mp[prefSum]));
        }
        else
        {
            // Only store the index of the
            // first occurrence of prefSum.
            mp[prefSum] = i;
        }
    }

    return maxLength;
}

int zeroSumSubmat(vector<vector<int>> &mat)
{
    int rows = mat.size();
    int cols = mat[0].size();
    int maxArea = 0;

    for (int i = 0; i < rows; i++)
    {

        // Temporary array to store
        // the column-wise cumulative sum.
        vector<int> temp(cols, 0);

        // Iterate over each row from i to j
        for (int j = i; j < rows; j++)
        {

            // Accumulate the column-wise
            // sum for rows between i and j.
            for (int k = 0; k < cols; k++)
                temp[k] += mat[j][k];

            // Find the longest zero-sum
            //  subarray in column sums.
            int len = maxZeroSumSubarray(temp);

            // Update the maximum area
            int curHeight = (j - i + 1);
            maxArea = max(maxArea, curHeight * len);
        }
    }

    return maxArea;
}

//Driver Code Starts

int main()
{
    vector<vector<int>> mat = {{9, 7, 16, 5},
                               {1, -6, -7, 3},
                               {1, 8, 7, 9},
                               {7, -2, 0, 10}};
    cout << zeroSumSubmat(mat) << endl;
    return 0;
}
//Driver Code Ends


